package com.utewedding.app.domain.entity;
import com.utewedding.app.domain.AccountingDocumentType; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="accounting_documents") public class AccountingDocumentEntity{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="order_id",nullable=false) private UUID orderId; @Column(name="document_number",nullable=false,unique=true,length=60) private String documentNumber;
 @Enumerated(EnumType.STRING) @Column(name="document_type",nullable=false,length=30) private AccountingDocumentType documentType;
 @Column(name="source_quality",nullable=false,length=40) private String sourceQuality="LIVE_SNAPSHOT"; @JdbcTypeCode(SqlTypes.JSON) @Column(name="buyer_snapshot",columnDefinition="jsonb",nullable=false) private String buyerSnapshot="{}";
 @Column(nullable=false) private long subtotal; @Column(name="product_discount",nullable=false) private long productDiscount; @Column(name="voucher_discount",nullable=false) private long voucherDiscount; @Column(name="shipping_fee",nullable=false) private long shippingFee; @Column(name="shipping_fee_before_discount",nullable=false) private long shippingFeeBeforeDiscount; @Column(name="shipping_discount_amount",nullable=false) private long shippingDiscountAmount; @Column(name="total_amount",nullable=false) private long totalAmount;
 @Column(nullable=false,length=3) private String currency="VND"; @Column(name="payment_method",length=40) private String paymentMethod; @Column(name="payment_reference",length=190) private String paymentReference; @Column(name="issued_at",nullable=false) private Instant issuedAt; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt;
 @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();} public UUID getId(){return id;} public UUID getOrderId(){return orderId;} public void setOrderId(UUID v){orderId=v;} public String getDocumentNumber(){return documentNumber;} public void setDocumentNumber(String v){documentNumber=v;} public AccountingDocumentType getDocumentType(){return documentType;} public void setDocumentType(AccountingDocumentType v){documentType=v;} public String getSourceQuality(){return sourceQuality;} public void setSourceQuality(String v){sourceQuality=v;} public String getBuyerSnapshot(){return buyerSnapshot;} public void setBuyerSnapshot(String v){buyerSnapshot=v;} public long getSubtotal(){return subtotal;} public void setSubtotal(long v){subtotal=v;} public long getProductDiscount(){return productDiscount;} public void setProductDiscount(long v){productDiscount=v;} public long getVoucherDiscount(){return voucherDiscount;} public void setVoucherDiscount(long v){voucherDiscount=v;} public long getShippingFee(){return shippingFee;} public void setShippingFee(long v){shippingFee=v;} public long getShippingFeeBeforeDiscount(){return shippingFeeBeforeDiscount;} public void setShippingFeeBeforeDiscount(long v){shippingFeeBeforeDiscount=v;} public long getShippingDiscountAmount(){return shippingDiscountAmount;} public void setShippingDiscountAmount(long v){shippingDiscountAmount=v;} public long getTotalAmount(){return totalAmount;} public void setTotalAmount(long v){totalAmount=v;} public String getCurrency(){return currency;} public void setCurrency(String v){currency=v;} public String getPaymentMethod(){return paymentMethod;} public void setPaymentMethod(String v){paymentMethod=v;} public String getPaymentReference(){return paymentReference;} public void setPaymentReference(String v){paymentReference=v;} public Instant getIssuedAt(){return issuedAt;} public void setIssuedAt(Instant v){issuedAt=v;}
}
